 await driver.send('touchEnd',[]);const after=await scanState(page);rec.pinch.after=after;rec.pinch.anchorErrorPx={x:after.image.x+sourceAnchor.x*after.image.width-cx,y:after.image.y+sourceAnchor.y*after.image.height-cy};
