 await driver.send('touchStart',[{x:cx-r0,y:cy},{x:cx+r0,y:cy}]);await driver.send('touchMove',[{x:cx-r0*1.05,y:cy},{x:cx+r0*1.05,y:cy}]);await page.locator('#locale').selectOption('en');await page.waitForFunction(()=>document.querySelector('.legal-lab')?.lang==='en');await driver.send('touchEnd',[]);rec.localeRerenderDuringGesture=true;await driver.close();
