async function chooseUnit(page,id,doc){
 const unit=doc.units.find(u=>u.id===id);assert.ok(unit,`unknown ${id}`);
 // Navigate through actual search results, including sections beyond first page.
 const input=page.locator('[data-input="reader-query"]');await input.fill(unit.text.trim().slice(0,70)||unit.locator);await input.press('Enter');
 await page.locator('.ll-search-results').waitFor();const result=page.locator(sel('jump-unit',`[data-id="${id}"]`));
 if(!await result.isVisible()){
  const section=doc.sections.find(s=>s.id===unit.sectionId);await page.locator(sel('clear-search')).click();
  if(!await page.locator(sel('section',`[data-id="${section.id}"]`)).isVisible())await page.locator(sel('toggle-toc')).click();
  await page.locator(sel('section',`[data-id="${section.id}"]`)).click();
  const pageIndex=Math.floor(section.unitIds.indexOf(id)/80);
  for(let i=0;i<pageIndex;i++)await page.locator(sel('reader-page',`[data-page="${i+1}"]`)).click();
 }else await result.click();
 const target=sel('select-unit',`[data-unit="${id}"]`);await page.locator(target).click();await pressed(page,target);
}
async function answerTask(page,t){
 if(t.kind==='scan'){const s=sel('hotspot',`[data-id="${t.answer}"]`);await page.locator(s).click();await pressed(page,s);}
 else if(t.kind==='type'){const s=sel('type-choice',`[data-value="${t.answer}"]`);await page.locator(s).click();await pressed(page,s);}
 else{if(t.kind==='history')await page.locator(sel('history-edition',`[data-id="${t.docId}"]`)).click();const doc=docs.find(d=>d.id===t.docId);for(const id of expandIds(t.answerSets[0],[doc]))await chooseUnit(page,id,doc);}
 await page.locator(sel('submit-task')).click();await page.locator('.ll-feedback.success').waitFor();
}
